$save=static function(array $data)use($stateFile):void{$tmp=$stateFile.'.tmp';file_put_contents($tmp,json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),LOCK_EX);rename($tmp,$stateFile);};
$canonical=static function(array $value):string{$normalize=function($v)use(&$normalize){if(!is_array($v))return $v;if(array_is_list($v))return array_map($normalize,$v);ksort($v,SORT_STRING);foreach($v as $k=>$item)$v[$k]=$normalize($item);return $v;};return json_encode($normalize($value),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);};
if($path==='/api/device/heartbeat'&&$method==='POST'){echo json_encode(['ok'=>true,'device_id'=>'agent-device-01']);exit;}
if($path==='/api/device/signing-key'&&$method==='POST'){$state['agent_public_key']=$body['public_key']??'';$save($state);$public=base64_decode((string)($state['server_public_key']??''),true);echo json_encode(['ok'=>true,'device_id'=>'agent-device-01','server_device_id'=>'server-device-01','server_public_key'=>$state['server_public_key'],'server_key_id'=>hash('sha256',$public)]);exit;}
if($path==='/api/device/tasks'&&$method==='GET'){$now=time();$envelope=['schema_version'=>1,'envelope_id'=>'env_'.str_repeat('a',32),'issuer_device_id'=>'server-device-01','issuer_key_id'=>hash('sha256',base64_decode($state['server_public_key'],true)),'task_id'=>'task-signed-smoke','target_device_id'=>'agent-device-01','action'=>'workspace.write','issued_at'=>gmdate('Y-m-d\\TH:i:s\\Z',$now),'expires_at'=>gmdate('Y-m-d\\TH:i:s\\Z',$now+120),'nonce'=>str_repeat('b',48),'payload'=>['actions'=>[['type'=>'write_file','path'=>'signed-agent-proof.txt','content'=>'DCP_SIGNED_AGENT_TASK_OK']]]];$secret=base64_decode($state['server_secret_key'],true);$signature=base64_encode(sodium_crypto_sign_detached($canonical($envelope),$secret));$state['issued_envelope_id']=$envelope['envelope_id'];$save($state);echo json_encode(['device_id'=>'agent-device-01','transport'=>'ed25519-v1','tasks'=>[['id'=>'task-signed-smoke','signed_envelope'=>$envelope,'signature'=>$signature]]]);exit;}
